def fizzbuzz(n: int) -> list[str]:
    """
    Devuelve una lista de strings del 1 al n, donde:
    - Multiplos de 3 son 'Fizz'
    - Multiplos de 5 son 'Buzz'
    - Multiplos de 15 son 'FizzBuzz'
    - Los demás son el número como string.
    """
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

def agrupar_por(items, clave):
    """
    Agrupa una lista de diccionarios por el valor de una clave específica.

    Args:
        items: Lista de diccionarios.
        clave: Clave a agrupar por.

    Returns:
        Diccionario con los items agrupados por el valor de la clave.
    """
    return dict(
        {clave: [item[clave] for item in items]}
