def mayor_racha(lista):
    """
    Encuentra la racha más larga de elementos consecutivos iguales.
    Devuelve la tupla (elemento, longitud). Si hay empate, devuelve la primera.
    Si la lista está vacía, devuelve None.
    """
    if not lista:
        return None

    max_racha = 1
    max_element = lista[0]
    current_racha = 1

    for i in range(1, len(lista)):
        if lista[i] == lista[i - 1]:
            current_racha += 1
        else:
            if current_racha > max_racha:
                max_racha = current_racha
                max_element = lista[i - 1]
            current_racha = 1

    # Verificar la racha final
    if current_racha > max_racha:
        max_racha = current_racha
        max_element = lista[-1]

    return (max_element, max_racha)

def primos(n: int) -> list[int]:
    """Devuelve la lista ordenada de todos los números primos menores o iguales a n."""
    if n < 2:
        return []
    return [i for i in range(2, n + 1) if all(i % j != 0 for j in range(2, int(i**0.5) + 1))]

def mcd(a, b):
    """
    Devuelve el máximo común divisor de dos enteros no negativos.
    El mcd de un número con 0 es ese número.
    """
    if b == 0:
        return a
    while b != 0:
        a, b = b, a % b
    return a

def comprimir(s: str) -> str:
    """Aplica codificación por repeticiones.

    'aaabb' se convierte en 'a3b2'.
    Si la versión comprimida no es más corta que la original,
    devuelve la original sin cambios.
    """
    if not s:
        return s

    # Contar frecuencias de cada carácter
    counts = {}
    for char in s:
        counts[char] = counts.get(char, 0) + 1

    # Construir la cadena comprimida
    compressed = []
    for char, count in counts.items():
        if count > 1:
            compressed.append(f"{char}{count}")
        else:
            compressed.append(char)

    compressed_str = "".join(compressed)

    # Verificar si es más corta
    if len(compressed_str) < len(s):
        return compressed_str
    else:
        return s

def balanceado(s: str) -> bool:
    """
    Verifica si los parentesis, corchetes y llaves del texto están correctamente
    balanceados y anidados.

    Args:
        s: La cadena de texto a verificar.

    Returns:
        True si los paréntesis, corchetes y llaves están balanceados,
        False en caso contrario.

    Un texto vacío es considerado balanceado.
    """
    if not s:
        return True

    open_paren = 0
    open_bracket = 0
    open_brace = 0

    for char in s:
        if char == '(':
            open_paren += 1
        elif char == '[':
            open_bracket += 1
        elif char == '{':
            open_brace += 1
        elif char == ')':
            if open_paren == 0:
                return False
            open_paren -= 1
        elif char == ']':
            if open_bracket == 0:
                return False
            open_bracket -= 1
        elif char == '}':
            if open_brace == 0:
                return False
            open_brace -= 1

    return open_paren == 0 and open_bracket == 0 and open_brace == 0

def transpuesta(m):
    """
    Recibe una matriz (lista de listas) y devuelve su transpuesta.
    Si la matriz está vacía, devuelve una lista vacia.
    """
    if not m:
        return []

    n = len(m)
    m_transpuesta = [[0] * n for _ in range(len(m[0]))]

    for i in range(len(m)):
        for j in range(len(m[0])):
            m_transpuesta[j][i] = m[i][j]

    return m_transpuesta

