def anidar(plano: dict) -> dict:
    """
    Recorre un diccionario plano y anida las claves que contienen puntos.

    Ejemplo: {'a.b': 1} -> {'a': {'b': 1}}

    Args:
        plano: Diccionario plano con claves que pueden contener puntos.

    Returns:
        Diccionario anidado con claves separadas por puntos.
    """
    result = {}
    for key, value in plano.items():
        if '.' in key:
            parts = key.split('.')
            current = result
            for part in parts[:-1]:
                if part not in current:
                    current[part] = {}
                current = current[part]
            current[parts[-1]] = value
        else:
            result[key] = value
    return result


