def formatear_bytes(n: int) -> str:
    """
    Convierte un número de bytes a texto legible usando múltiplos de 1024
    y las unidades B, KB, MB, GB.

    Ejemplo: 1536 -> '1.5 KB'
    """
    if n < 0:
        raise ValueError("El número de bytes debe ser no negativo.")

    unidades = [
        ("B", 1),
        ("KB", 1024),
        ("MB", 1024 ** 2),
        ("GB", 1024 ** 3),
    ]

    for unidad, factor in unidades:
        if n >= factor:
            valor = n // factor
            decimal = n % factor
            if decimal == 0:
                return f"{valor} {unidad}"
            else:
                return f"{valor}.{decimal:.1f} {unidad}"

    return f"{n} B"

def parsear_query(s: str) -> dict:
    """
    Convierte un query string tipo 'a=1&b=2' en un dict {'a':'1','b':'2'}.
    Una clave sin valor ('c=') queda con string vacio.
    String vacio devuelve dict vacio.
    """
    if not s:
        return {}
    result = {}
    for part in s.split("&"):
        if "=" in part:
            key, value = part.split("=", 1)
            result[key] = value
    return result

