def sumar_romanos(a: str, b: str) -> str:
    """
    Suma dos números romanos y devuelve el resultado en romano.

    Args:
        a: Primer número en formato romano.
        b: Segundo número en formato romano.

    Returns:
        El resultado de la suma en formato romano.
    """
    def valor_romano(s: str) -> int:
        valores = {
            "I": 1, "V": 5, "X": 10, "L": 50,
            "C": 100, "D": 500, "M": 1000
        }
        total = 0
        for i in range(len(s) - 1, -1, -1):
            total += valores[s[i]]
            if i > 0 and valores[s[i]] < valores[s[i - 1]]:
                total -= valores[s[i]]
        return total

    def romano_de_numero(n: int) -> str:
        if n == 0:
            return ""
        if n < 10:
            return str(n)
        if n < 40:
            return "X" + romano_de_numero(n - 10)
        if n < 50:
            return "L" + romano_de_numero(n - 50)
        if n < 100:
            return "C" + romano_de_numero(n - 100)
        if n < 400:
            return "D" + romano_de_numero(n - 500)
        if n < 1000:
            return "M" + romano_de_numero(n - 1000)
        return romano_de_numero(n - 1000)

    a_val = valor_romano(a)
    b_val = valor_romano(b)
    resultado = a_val + b_val
    return romano_de_numero(resultado)


